<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useToast } from 'vue-toastification'
import { useI18n } from 'vue-i18n'
import ErpField from '@/components/erp/ErpField.vue'
import ErpSearchField from '@/components/erp/ErpSearchField.vue'
import MasterDataApi, { type EducationalCatalog, type MasterDataRecord } from '@/api/educationalMasterData'
import { moveCreatedRowFirst } from '@/utils/createdFirst'
import { confirmActionWarning } from '@/composables/useActionWarning'

const toast = useToast()
const { t } = useI18n()
type Catalog = Exclude<EducationalCatalog, 'times' | 'durations' | 'teachers' | 'classes'>
type CatalogRow = MasterDataRecord
const catalog = ref<Catalog>('countries')
const rows = ref<CatalogRow[]>([])
const countries = ref<MasterDataRecord[]>([])
const dialog = ref(false)
const editing = ref<CatalogRow | null>(null)
const pendingDelete = ref<CatalogRow | null>(null)
const deleteDialog = ref(false)
const loading = ref(false)
const saving = ref(false)
const search = ref('')
const form = ref<Partial<CatalogRow>>({ name: '', is_active: true })
const initialForm = ref('')
const labels = computed<Record<Catalog, string>>(() => ({ countries: t('educational.masterData.countries'), 'education-levels': t('educational.masterData.educationLevels'), languages: t('educational.masterData.languages'), universities: t('educational.masterData.universities'), semesters: t('educational.semester'), subjects: t('educational.masterData.subjects'), tests: t('educational.masterData.tests'), skills: t('educational.masterData.skills'), programs: t('educational.masterData.programs'), scholarships: t('erp.scholarship'), provinces: t('educational.masterData.provinces'), 'english-levels': t('educational.masterData.englishLevels'), 'acquisition-routes': t('educational.masterData.acquisitionRoutes') }))
const hasCode = computed(() => ['countries', 'languages', 'semesters'].includes(catalog.value))
// Programs no longer carry a display order; their sort_order column was dropped.
const isSortedCatalog = computed(() => ['education-levels', 'semesters', 'subjects', 'tests', 'skills', 'scholarships', 'provinces', 'english-levels', 'acquisition-routes'].includes(catalog.value))
const hasContact = computed(() => ['countries', 'universities'].includes(catalog.value))
const filteredRows = computed(() => { const query = search.value.trim().toLocaleLowerCase(); return !query ? rows.value : rows.value.filter(row => [row.name, row.code, row.phone, row.email, row.city, row.contact, row.description].filter(Boolean).some(value => String(value).toLocaleLowerCase().includes(query))) })
const headers = computed(() => [{ title: t('common.fields.name'), key: 'name' }, ...(hasCode.value ? [{ title: t('common.fields.code'), key: 'code' }] : []), { title: t('educational.masterData.details'), key: 'details' }, { title: t('common.fields.status'), key: 'status' }, { title: t('common.messages.actions'), key: 'actions', sortable: false, align: 'end' as const }])
const snapshot = () => JSON.stringify(form.value)
const isDirty = computed(() => snapshot() !== initialForm.value)
async function load() { loading.value = true; try { const [catalogRows, countryRows] = await Promise.all([MasterDataApi.list(catalog.value), MasterDataApi.list('countries')]); rows.value = catalogRows; countries.value = countryRows } catch { toast.error(t('educational.masterData.loadFailed')) } finally { loading.value = false } }
function open(row?: CatalogRow) { editing.value = row ?? null; form.value = row ? { ...row } : { name: '', code: '', description: '', sort_order: 0, is_active: true }; initialForm.value = snapshot(); dialog.value = true }
async function requestClose() { if (isDirty.value && !await confirmActionWarning({ key: 'discard-form-changes', title: t('common.actionWarnings.discardTitle'), message: t('common.actionWarnings.discardMessage'), confirmText: t('common.actionWarnings.discardConfirm'), cancelText: t('common.actions.cancel'), icon: 'tabler-file-alert', tone: 'primary' })) return; dialog.value = false }
async function save() { if (!form.value.name?.trim()) return; saving.value = true; try { const payload = { ...form.value, name: form.value.name.trim(), code: form.value.code?.trim() || undefined }; const wasNew = !editing.value; const saved = editing.value ? await MasterDataApi.update(catalog.value, editing.value.id, payload) : await MasterDataApi.create(catalog.value, payload); dialog.value = false; await load(); if (wasNew) rows.value = moveCreatedRowFirst(rows.value, saved); toast.success(t('educational.masterData.saved')) } catch (error: any) { toast.error(error.message ?? t('educational.masterData.saveFailed')) } finally { saving.value = false } }
function requestDelete(row: CatalogRow) { pendingDelete.value = row; deleteDialog.value = true }
async function remove() { if (!pendingDelete.value) return; saving.value = true; try { await MasterDataApi.remove(catalog.value, pendingDelete.value.id); await load(); deleteDialog.value = false; pendingDelete.value = null } catch (error: any) { toast.error(error.message ?? t('educational.masterData.inUse')) } finally { saving.value = false } }
watch(catalog, async () => { search.value = ''; await load() })
onMounted(load)
</script>

<template>
  <div class="education-workspace">
    <div class="education-workspace__heading"><VBreadcrumbs :items="[{ title: t('erp.home'), to: { name: 'home' } }, { title: t('common.navigation.options'), disabled: true }]" density="compact" class="pa-0" /><h1 class="text-h5 font-weight-bold mb-0">{{ t('common.navigation.educationalData') }}</h1></div>
    <VCard class="education-panel">
      <VCardText class="education-toolbar pa-4"><VRow align="center" class="ma-0"><VCol cols="12" md="6" lg="5"><ErpSearchField v-model="search" :placeholder="t('common.actions.search')" /></VCol><VCol cols="12" md="6" lg="7" class="d-flex justify-md-end"><VBtn color="primary" prepend-icon="tabler-plus" @click="open()">{{ t('common.actions.add') }}</VBtn></VCol></VRow></VCardText>
      <VTabs v-model="catalog" show-arrows class="education-tabs px-4"><VTab v-for="(label, key) in labels" :key="key" :value="key">{{ label }}</VTab></VTabs><VDivider />
      <ResponsiveDataTable :items="filteredRows" :headers="headers" item-value="id" class="education-table" :loading="loading" :skeleton-rows="6" mobile-cards mobile-expand-all mobile-title-key="name" mobile-action-key="actions" :sticky-key-column="false" :sticky-action-column="false">
        <template #item.details="{ item }">{{ item.phone || item.email || item.city || item.portal_url || item.contact || item.description || '—' }}</template>
        <template #item.status="{ item }"><VChip :color="item.is_active ? 'success' : 'secondary'" size="small" variant="tonal">{{ item.is_active ? t('common.statuses.active') : t('common.statuses.inactive') }}</VChip></template>
        <template #item.actions="{ item }"><VMenu location="bottom end"><template #activator="{ props }"><VBtn v-bind="props" icon="tabler-dots-vertical" size="small" variant="tonal" :aria-label="t('common.messages.actions')" /></template><VList density="compact"><VListItem prepend-icon="tabler-pencil" :title="t('common.actions.edit')" @click="open(item)" /><VListItem prepend-icon="tabler-trash" class="education-table__delete" :title="t('common.actions.delete')" @click="requestDelete(item)" /></VList></VMenu></template>
        <template #no-data><div class="education-empty-state"><TableEmptyState icon="tabler-database-off" :min-height="0" :title="t('$vuetify.noDataText')" :description="search ? t('$vuetify.dataIterator.noResultsText') : labels[catalog]" /></div></template>
      </ResponsiveDataTable>
    </VCard>
  </div>
  <VDialog :model-value="dialog" max-width="760" scrollable content-class="education-editor-dialog" @update:model-value="value => { if (!value) void requestClose() }"><VCard class="education-editor"><VCardTitle class="education-editor__header px-5 py-4"><span>{{ t(editing ? 'common.actions.editItem' : 'common.actions.addItem', { item: labels[catalog] }) }}</span><VSpacer /><VBtn icon="tabler-x" variant="tonal" color="error" class="education-editor__close" :disabled="saving" :aria-label="t('common.actions.close')" @click="requestClose" /></VCardTitle><VCardText class="education-editor__body pa-5"><VForm @submit.prevent="save"><VRow><VCol cols="12" md="6"><ErpField v-model="form.name" required :label="t('common.fields.name')" :placeholder="t('common.fields.name')" /></VCol><VCol v-if="hasCode" cols="12" md="6"><ErpField v-model="form.code" required :label="t('common.fields.code')" :placeholder="t('common.fields.code')" /></VCol><VCol v-if="isSortedCatalog" cols="12" md="6"><ErpField v-model.number="form.sort_order" type="number" min="0" :label="t('educational.masterData.displayOrder')" :placeholder="t('educational.masterData.displayOrder')" /></VCol><VCol v-if="catalog === 'universities'" cols="12" md="6"><ErpField v-model="form.country_id" kind="select" :items="countries.filter(item => item.is_active).map(item => ({ title: item.name, value: item.id }))" :label="t('educational.country')" :placeholder="t('educational.country')" clearable /></VCol><VCol v-if="catalog === 'universities'" cols="12" md="6"><ErpField v-model="form.city" :label="t('educational.masterData.city')" :placeholder="t('educational.masterData.city')" /></VCol><VCol v-if="catalog === 'universities'" cols="12" md="6"><ErpField v-model="form.website" :label="t('educational.masterData.website')" :placeholder="t('educational.masterData.website')" /></VCol><template v-if="hasContact"><VCol cols="12" md="6"><ErpField v-model="form.phone" :label="t('educational.masterData.phone')" :placeholder="t('educational.masterData.phone')" /></VCol><VCol cols="12" md="6"><ErpField v-model="form.email" type="email" :label="t('educational.masterData.email')" :placeholder="t('educational.masterData.email')" /></VCol><VCol cols="12"><ErpField v-model="form.portal_url" :label="t('educational.masterData.portalUrl')" :placeholder="t('educational.masterData.portalUrl')" /></VCol></template><VCol v-if="!hasCode" cols="12"><ErpField v-model="form.description" kind="textarea" :label="t('common.fields.description')" :placeholder="t('common.fields.description')" rows="3" /></VCol><VCol cols="12"><VSwitch v-model="form.is_active" color="success" inset :label="t('common.statuses.active')" hide-details /></VCol></VRow></VForm></VCardText><VCardActions class="education-editor__footer justify-end px-5 py-4"><VBtn class="education-editor__cancel" :disabled="saving" @click="requestClose">{{ t('common.actions.cancel') }}</VBtn><VBtn class="education-editor__save" :loading="saving" :disabled="!form.name?.trim()" @click="save">{{ t('common.actions.save') }}</VBtn></VCardActions></VCard></VDialog>
  <VDialog v-model="deleteDialog" max-width="480" content-class="education-delete-overlay"><VCard class="education-delete-dialog"><VCardText class="education-delete-dialog__content"><div class="education-delete-dialog__icon"><VIcon icon="tabler-trash" size="30" /></div><h2>{{ t('common.actions.delete') }}</h2><p>{{ t('educational.masterData.removeConfirm', { name: pendingDelete?.name ?? '' }) }} {{ t('common.confirmations.thisActionCannotBeUndone') }}</p></VCardText><VCardActions class="education-delete-dialog__actions"><VBtn class="education-editor__cancel" :disabled="saving" @click="deleteDialog = false">{{ t('common.actions.cancel') }}</VBtn><VBtn class="education-delete-dialog__confirm" color="error" :loading="saving" @click="remove">{{ t('common.actions.delete') }}</VBtn></VCardActions></VCard></VDialog>
</template>

<style lang="scss">
.education-workspace { display: flex; flex-direction: column; gap: .75rem; }.education-workspace__heading { display: flex; flex-direction: column; gap: .15rem; }.education-workspace__heading h1 { line-height: 1.35; }.education-panel { overflow: hidden; border: 1px solid rgba(var(--v-border-color), var(--v-border-opacity)); border-radius: .9rem; }.education-toolbar { border-block-end: 1px solid rgba(var(--v-border-color), var(--v-border-opacity)); }.education-tabs { background: transparent; }.education-table .v-table__wrapper > table > thead > tr > th { background: rgba(var(--v-theme-on-surface), .045); font-size: .82rem; font-weight: 700; letter-spacing: .025em; white-space: nowrap; }.education-table .v-table__wrapper > table > tbody > tr > td { white-space: nowrap; }.education-table .v-table__wrapper:has(.education-empty-state) { overflow-x: hidden; }.education-table .v-table__wrapper > table:has(.education-empty-state) { min-inline-size: 100%; }.education-table .v-table__wrapper > table:has(.education-empty-state) > tbody > tr > td { padding: 0 !important; }.education-empty-state { display: grid; min-block-size: 17rem; place-items: center; }.education-table__delete { color: rgb(var(--v-theme-error)) !important; }
.education-editor, .education-delete-dialog { overflow: hidden; background: rgb(var(--v-theme-surface)); }.education-editor__header, .education-editor__footer { display: flex; align-items: center; border-color: rgba(var(--v-border-color), .52); border-style: solid; border-width: 0; background: color-mix(in srgb, rgb(var(--v-theme-surface)) 93%, rgb(var(--v-theme-on-surface)) 7%); }.education-editor__header { border-block-end-width: 1px; font-size: 1.2rem; font-weight: 700; }.education-editor__footer { gap: .75rem; border-block-start-width: 1px; }.education-editor__body { background: rgba(var(--v-theme-on-surface), .018); }.education-editor__close { border: 1px solid rgba(var(--v-theme-error), .4) !important; border-radius: 999px !important; }.education-editor__save { background: rgb(var(--v-theme-primary)) !important; color: rgb(var(--v-theme-on-primary)) !important; }.education-editor__cancel { border: 1px solid rgba(var(--v-theme-secondary), .5) !important; background: rgba(var(--v-theme-secondary), .13) !important; color: rgb(var(--v-theme-secondary)) !important; }
.education-delete-dialog__content { display: flex; flex-direction: column; align-items: center; padding: 2rem 2rem 1.25rem !important; text-align: center; }.education-delete-dialog__content h2 { margin: 0; font-size: 1.2rem; }.education-delete-dialog__content p { max-inline-size: 22rem; margin: .65rem 0 0; color: rgba(var(--v-theme-on-surface), var(--v-medium-emphasis-opacity)); }.education-delete-dialog__icon { display: grid; inline-size: 4.25rem; block-size: 4.25rem; margin-block-end: 1.25rem; border-radius: 50%; background: rgba(var(--v-theme-error), .14); color: rgb(var(--v-theme-error)); place-items: center; }.education-delete-dialog__actions { display: grid !important; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .75rem; padding: 0 2rem 2rem !important; }.education-delete-dialog__actions .v-btn { min-block-size: 2.85rem; }.education-delete-dialog__confirm { background: rgb(var(--v-theme-error)) !important; color: rgb(var(--v-theme-on-error)) !important; }.v-overlay:has(.education-editor-dialog) .v-overlay__scrim, .v-overlay:has(.education-delete-overlay) .v-overlay__scrim { background: rgba(20, 25, 35, .3) !important; backdrop-filter: blur(6px); opacity: 1 !important; }
</style>
